// ⚙️  SETTINGS — the only node you need to edit.
// Every other node reads its values from here. After filling it in, keep this
// workflow private: it holds your WhatsApp token.

const SETTINGS = {
  // Who gets new-request alerts, and who may send PAID / RESEND / PENDING.
  // Country code + number, digits only. Add teammates to the list.
  adminNumbers: ['918744855792'],

  // Must match AUTOMATION_KEY in the app: src/config/automation.ts
  appKey: 'wrc-app-c5hxrzfh4aq5qemf6h4nejff',

  // Must match src/config/activation.json in the app — the key that signs codes.
  activationSecret: 'U9fdxiZl_DiXV6n310z-rePks9FFMhks',

  whatsapp: {
    // WhatsApp Cloud API (Meta). developers.facebook.com → your app → WhatsApp → API Setup
    graphBase: 'https://graph.facebook.com/v23.0',
    phoneNumberId: '',        // "Phone number ID" (not the phone number itself)
    accessToken: '',          // permanent System User token (the API Setup one expires in 24 h)
    verifyToken: 'wrc-verify-re2m0q5g2pjd822r', // type this same text in Meta → WhatsApp → Configuration → Webhook
    appSecret: '',            // Meta app → App settings → Basic → App secret. Proves a message really came from Meta.
    skipSignatureCheck: false,  // never true on a public URL

    // Messages you start (the alert to you, the code to the customer) must be
    // approved templates. Names below must match WhatsApp Manager exactly.
    // false = plain text, which only works within 24 h of that person messaging
    // your WhatsApp number (handy for a first demo on the test number).
    useTemplates: true,
    templateLanguage: 'en',
    adminAlertTemplate: 'wrc_diamond_request', // body variables: {{1}} ref, {{2}} name, {{3}} mobile, {{4}} best time, {{5}} ref again
    customerCodeTemplate: 'wrc_diamond_code',  // body variables: {{1}} name, {{2}} code, {{3}} ref
  },

  sms: {
    // Used when WhatsApp fails. Fast2SMS "Quick SMS" works without DLT (needs a
    // ₹100 recharge + KYC). With no key yet, an SMS attempt simply fails and
    // the ✅/⚠️ reply tells you to read the code out on the call.
    url: 'https://www.fast2sms.com/dev/bulkV2',
    apiKey: '',
  },
};

// Which door this run came in through.
const route = $('WhatsApp · verify').isExecuted
  ? 'verify'
  : $('WhatsApp · events').isExecuted
    ? 'event'
    : 'request';

return $input.all().map((item) => ({
  json: { route, cfg: SETTINGS, req: item.json },
  binary: item.binary,
}));

// Checks what the app sent before anything is stored or anyone is messaged.
const { cfg, req } = $input.first().json;
const body = req.body && typeof req.body === 'object' ? req.body : {};
const headers = req.headers || {};
const fail = (status, error) => [{ json: { ok: false, status, error } }];

const key = String(headers['x-wrc-key'] ?? body.key ?? '');
if (!cfg.appKey || key !== cfg.appKey) return fail(401, 'Unknown app key');

const reference = String(body.reference ?? '').trim().toUpperCase();
if (!/^WRC-D[0-9A-Z]{6}$/.test(reference)) return fail(400, 'Bad reference');

const digits = String(body.phone ?? '').replace(/\D/g, '').replace(/^(?:91|0)(?=\d{10}$)/, '');
if (!/^[6-9]\d{9}$/.test(digits)) return fail(400, 'Bad mobile number');

// Template variables may not hold newlines or long runs of spaces.
const clean = (value, max) =>
  String(value ?? '').replace(/[\r\n\t]+/g, ' ').replace(/ {2,}/g, ' ').trim().slice(0, max);
const email = clean(body.email, 120);
const TIMES = { any: 'Any time', morning: 'Morning (9-12)', afternoon: 'Afternoon (12-5)', evening: 'Evening (5-8)' };

return [{
  json: {
    ok: true,
    row: {
      reference,
      name: clean(body.name, 60) || 'Customer',
      phone: '91' + digits,
      email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : '',
      bestTime: TIMES[body.bestTime] || 'Any time',
      status: 'pending',
      requestedAt: new Date().toISOString(),
      adminAlert: 'sending',
      adminAlertId: '',
      paidAt: '',
      amount: '',
      code: '',
      codeVia: '',
      codeMessageId: '',
    },
  },
}];

// One alert per admin number, as a template (or plain text — see Settings).
const cfg = $('Settings').first().json.cfg;
const row = $('Check request').first().json.row;
const pretty = (p) => '+' + p.slice(0, 2) + ' ' + p.slice(2, 7) + ' ' + p.slice(7);
const text =
  '💎 New Diamond request ' + row.reference + '\n' +
  'Name: ' + row.name + '\n' +
  'Mobile: ' + pretty(row.phone) + '\n' +
  'Best time: ' + row.bestTime +
  (row.email ? '\nEmail: ' + row.email : '') + '\n\n' +
  'Call them, take the payment, then reply:\nPAID ' + row.reference;
const smsText = 'WRC: New Diamond request ' + row.reference + ' from ' + row.name + ', ' + pretty(row.phone) +
  '. After payment reply on WhatsApp: PAID ' + row.reference;

return cfg.adminNumbers.map((to) => {
  const message = cfg.whatsapp.useTemplates
    ? {
        messaging_product: 'whatsapp', to, type: 'template',
        template: {
          name: cfg.whatsapp.adminAlertTemplate,
          language: { code: cfg.whatsapp.templateLanguage },
          components: [{ type: 'body', parameters: [
            { type: 'text', text: row.reference },
            { type: 'text', text: row.name },
            { type: 'text', text: pretty(row.phone) },
            { type: 'text', text: row.bestTime },
            { type: 'text', text: row.reference }, // {{5}}: the reference again, in "reply PAID …"
          ] }],
        },
      }
    : { messaging_product: 'whatsapp', to, type: 'text', text: { preview_url: false, body: text } };
  return { json: { to, message, smsText, reference: row.reference } };
});

// ── HMAC-SHA256, in plain JavaScript ────────────────────────────────────────
// n8n's Code node may not load Node's 'crypto' module (NODE_FUNCTION_ALLOW_BUILTIN),
// so the two hashes this workflow needs are done by hand. Checked against Node's
// crypto and against the app's own activation codes.
function sha256(bytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const len = bytes.length;
  const total = ((len + 9 + 63) >> 6) << 6;
  const m = new Uint8Array(total);
  m.set(bytes); m[len] = 0x80;
  const bits = len * 8;
  const view = new DataView(m.buffer);
  view.setUint32(total - 8, Math.floor(bits / 0x100000000));
  view.setUint32(total - 4, bits >>> 0);
  const w = new Uint32Array(64);
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < total; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = r(w[i-15], 7) ^ r(w[i-15], 18) ^ (w[i-15] >>> 3);
      const s1 = r(w[i-2], 17) ^ r(w[i-2], 19) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  const out = new Uint8Array(32);
  const ov = new DataView(out.buffer);
  H.forEach((v, i) => ov.setUint32(i * 4, v));
  return out;
}
function hmacSha256(keyBytes, msgBytes) {
  let key = keyBytes.length > 64 ? sha256(keyBytes) : keyBytes;
  const k = new Uint8Array(64); k.set(key);
  const ipad = new Uint8Array(64 + msgBytes.length), opad = new Uint8Array(64 + 32);
  for (let i = 0; i < 64; i++) { ipad[i] = k[i] ^ 0x36; opad[i] = k[i] ^ 0x5c; }
  ipad.set(msgBytes, 64);
  opad.set(sha256(ipad), 64);
  return sha256(opad);
}
const utf8 = (text) => new TextEncoder().encode(String(text));
const toHex = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');

// Reads what Meta sent: commands from an admin, or a message that failed.
const { cfg, req } = $input.first().json;

// 1. Prove it came from Meta — the X-Hub-Signature-256 header is an HMAC of the
//    exact bytes received, keyed with your app secret.
if (!cfg.whatsapp.skipSignatureCheck) {
  const header = String((req.headers || {})['x-hub-signature-256'] || '');
  if (!cfg.whatsapp.appSecret) throw new Error('Settings: whatsapp.appSecret is empty — messages cannot be checked.');
  let raw;
  try {
    raw = await this.helpers.getBinaryDataBuffer(0, 'data');
  } catch (error) {
    throw new Error('Raw body missing: the "WhatsApp · events" webhook needs Options → Raw Body on.');
  }
  const expected = 'sha256=' + toHex(hmacSha256(utf8(cfg.whatsapp.appSecret), new Uint8Array(raw)));
  if (header !== expected) return []; // not from Meta: ignore silently
}

const payload = req.body && typeof req.body === 'object' ? req.body : {};
const admins = new Set(cfg.adminNumbers.map(String));
const items = [];

for (const entry of payload.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    for (const message of value.messages || []) {
      const from = String(message.from || '');
      if (!admins.has(from)) continue; // only admins can give commands
      // Typed text, or a template quick-reply button's payload if you add one later.
      const text = String(message.text?.body ?? message.button?.payload ?? message.button?.text ?? message.interactive?.button_reply?.id ?? '').trim();
      const upper = text.toUpperCase().replace(/s+/g, ' ');
      const verb = (upper.match(/^[A-Z]+/) || [''])[0];
      const rest = upper.slice(verb.length).trim();
      let cmd = 'HELP';
      if (['PAID', 'PAYMENT', 'CONFIRM', 'CONFIRMED', 'DONE'].includes(verb)) cmd = 'PAID';
      else if (['RESEND', 'CODE'].includes(verb)) cmd = 'RESEND';
      else if (['PENDING', 'LIST', 'REQUESTS'].includes(verb)) cmd = 'PENDING';
      // "WRC-D7K3P9Q", "wrc d7k3p9q", "D7K3P9Q" and "7K3P9Q" all mean the same request.
      // O → 0 and I/L → 1, as in the app: references never use O, I or L.
      const m = rest.match(/^(?:WRC ?-? ?)?D?([0-9A-Z]{6})(?![0-9A-Z])(.*)$/);
      const ref = m ? 'WRC-D' + m[1].replace(/O/g, '0').replace(/[IL]/g, '1') : '';
      const amount = m ? ((m[2].match(/([0-9][0-9,]*(?:.[0-9]{1,2})?)/) || [])[1] || '').replace(/,/g, '') : '';
      if ((cmd === 'PAID' || cmd === 'RESEND') && !ref) cmd = 'HELP';
      items.push({ json: { kind: 'command', cmd, ref, amount: cmd === 'PAID' ? amount : '', from, text, messageId: message.id } });
    }
    for (const status of value.statuses || []) {
      if (status.status !== 'failed') continue;
      items.push({ json: { kind: 'failed', messageId: String(status.id), to: String(status.recipient_id || ''), error: status.errors?.[0]?.code ?? '' } });
    }
  }
}
return items;

