const utf8 = (text) => new TextEncoder().encode(String(text));
const toHex = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
// ── The Diamond activation code — must match src/lib/activation.ts ─────────
const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
function activationCode(secret, reference) {
  const sig = hmacSha256(utf8(secret), utf8(String(reference).trim().toUpperCase()));
  let bits = 0, value = 0, code = '';
  for (const byte of sig) {
    value = (value << 8) | byte; bits += 8;
    while (bits >= 5 && code.length < 8) { code += ALPHABET[(value >>> (bits - 5)) & 31]; bits -= 5; }
    if (code.length >= 8) break;
  }
  return code.slice(0, 4) + '-' + code.slice(4);
