// Works out what PAID / RESEND should do for this reference.
const cfg = $('Settings').first().json.cfg;
const command = $('Read WhatsApp event').item.json;
const row = $input.item.json;
const pretty = (p) => '+' + p.slice(0, 2) + ' ' + p.slice(2, 7) + ' ' + p.slice(7);

if (!row.reference) {
  return { json: { action: 'reply', to: command.from, text: '❓ No request ' + command.ref + ' found. Check the reference on the customer\'s Membership screen, or send PENDING for the list.' } };
}
