  ? {
      messaging_product: 'whatsapp', to: row.phone, type: 'template',
      template: {
        name: cfg.whatsapp.customerCodeTemplate,
        language: { code: cfg.whatsapp.templateLanguage },
        components: [{ type: 'body', parameters: [
          { type: 'text', text: row.name },
          { type: 'text', text: code },
          { type: 'text', text: row.reference },
        ] }],
      },
    }
  : { messaging_product: 'whatsapp', to: row.phone, type: 'text', text: { preview_url: false, body:
      'Hi ' + row.name + ', your payment is confirmed. Your WRC Diamond activation code is ' + code +
      ' (request ' + row.reference + '). Open WRC → Profile → Membership and enter it.' } };

return { json: {
  action: 'send',
  admin: command.from,
  reference: row.reference,
  name: row.name,
  phone: row.phone,
  phonePretty: pretty(row.phone),
  code,
  amount: command.amount || row.amount || '',
  repeat: row.status === 'paid',
  message,
  smsText: 'WRC: Payment confirmed. Your Diamond activation code is ' + code + ' for request ' + row.reference + '. Enter it in WRC > Profile > Membership.',
} };

const p = $input.item.json;
// A repeat PAID keeps the first payment time.
return { json: { status: 'paid', ...(p.repeat ? {} : { paidAt: new Date().toISOString() }), amount: p.amount, code: p.code } };

const p = $('Prepare code').item.json;
const via = $('Row · code on WhatsApp').isExecuted ? 'whatsapp' : $('Row · code by SMS').isExecuted ? $('Row · code by SMS').item.json.codeVia : 'failed';
const how = { whatsapp: 'on WhatsApp', sms: 'by SMS' }[via];
const head = how
  ? '✅ ' + (p.repeat ? 'Code sent again' : 'Payment noted') + ' for ' + p.reference + '. Code sent to ' + p.name + ' (' + p.phonePretty + ') ' + how + '.'
  : '⚠️ ' + p.reference + ': WhatsApp and SMS both failed. Read the code to ' + p.name + ' on ' + p.phonePretty + '.';
return { json: { to: p.admin, text: head + '\nCode: ' + p.code + (p.amount ? '\nAmount: ₹' + p.amount : '') } };

const rows = $input.all().map((i) => i.json).filter((r) => r.reference);
const to = $('Read WhatsApp event').first().json.from;
if (rows.length === 0) return [{ json: { to, text: '📭 No open Diamond requests.' } }];
rows.sort((a, b) => String(a.requestedAt).localeCompare(String(b.requestedAt)));
const pretty = (p) => '+' + p.slice(0, 2) + ' ' + p.slice(2, 7) + ' ' + p.slice(7);
const lines = rows.slice(-15).map((r) => '• ' + r.reference + ' — ' + r.name + ', ' + pretty(r.phone) + ' (' + r.bestTime + ')');
return [{ json: { to, text: '📋 Open Diamond requests (' + rows.length + '):\n' + lines.join('\n') + '\n\nReply PAID <reference> after payment.' } }];

return { json: { to: $input.item.json.from, text:
  'WRC Diamond commands:\n' +
  '• PAID WRC-DXXXXXX — payment received, send the code\n' +
  '• PAID WRC-DXXXXXX 4999 — same, and note the amount\n' +
  '• RESEND WRC-DXXXXXX — send the code again\n' +
  '• PENDING — list open requests' } };

